import heapq


def _dependency_solver(data, component):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    policies = {
        "component_01": (True, True),
        "component_02": (False, False),
        "component_03": (True, False),
        "component_04": (False, True),
        "component_05": (True, True),
    }
    minimize, descending = policies[component]
    order = list(reversed(names)) if descending else names
    choices = []
    for name in names:
        allowed = sorted(row["version"] for row in packages[name]
                         if row["version"] not in blocked.get(name, [])
                         and (name not in pins or row["version"] == pins[name]))
        choices.append([-1] + allowed)
    best_score = None
    best = None
    for values in product(*choices):
        assignment = dict(zip(names, values))
        valid = True
        for name, bounds in roots.items():
            version = assignment[name]
            if version < bounds[0] or version > bounds[1]:
                valid = False
                break
        if not valid:
            continue
        rows_by_name = {name: {row["version"]: row for row in rows}
                        for name, rows in packages.items()}
        edges = {}
        for name, version in assignment.items():
            if version < 0:
                continue
            row = rows_by_name[name][version]
            deps = [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            edges[name] = []
            for dep in deps:
                other = assignment[dep["name"]]
                if other < dep["min"] or other > dep["max"]:
                    valid = False
                    break
                edges[name].append(dep["name"])
            if not valid:
                break
        if not valid:
            continue
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if any(assignment[name] < 0 for name in reachable):
            continue
        if reachable != {name for name, version in assignment.items() if version >= 0}:
            continue
        visiting, finished = set(), set()
        def visit(name):
            if name in visiting:
                return False
            if name in finished:
                return True
            visiting.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            visiting.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in reachable):
            continue
        score = tuple(assignment[name] for name in order)
        if best_score is None or (score < best_score if minimize else score > best_score):
            best_score, best = score, assignment
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": {name: version for name, version in best.items() if version >= 0}}


def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    rounding = data["rounding"]
    def rounded(numerator):
        if rounding == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if any(job["id"] in blocked for job in subset) or not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit_for.get(data["source"], 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    start_state = (data["source"], 0, initial_mask)
    distances = {start_state: data["start"]}
    queue = [(data["start"], data["source"], 0, initial_mask)]
    while queue:
        time, node, spent, mask = heapq.heappop(queue)
        state = (node, spent, mask)
        if distances.get(state) != time:
            continue
        if node == data["target"] and spent == data["coupons"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], spent)]
            if spent < data["coupons"]:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, spent + 1))
            for duration, next_spent in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit_for.get(nxt, 0)
                next_state = (nxt, next_spent, next_mask)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_spent, next_mask))
    return {"arrival": None}


def _dep(component):
    return lambda data: _dependency_solver(data, component)

